const express = require('express');
const { MongoClient } = require('mongodb');
const crypto = require('crypto');

const app = express();
// Only trust the immediate loopback proxy rather than blindly trusting
// client-supplied X-Forwarded-For headers (prevents rate-limit spoofing).
app.set('trust proxy', 'loopback');

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';
const DB_NAME = 'appdb';

let db;

async function initDb() {
  const client = await MongoClient.connect(MONGO_URI);
  db = client.db(DB_NAME);
}

// Middleware: parse JSON body
app.use(express.json());

// Middleware: rate limiting by IP (trust proxy for X-Forwarded-For)
const rateLimitMap = new Map();
app.use((req, res, next) => {
  const ip = req.ip;
  const now = Date.now();
  const entry = rateLimitMap.get(ip) || { count: 0, resetAt: now + 60000 };
  if (now > entry.resetAt) {
    entry.count = 0;
    entry.resetAt = now + 60000;
  }
  entry.count++;
  rateLimitMap.set(ip, entry);
  if (entry.count > 100) {
    return res.status(429).json({ error: 'Rate limited' });
  }
  next();
});

// Auth middleware
function authenticate(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token || typeof token !== 'string' || token.length < 16) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.userId = token.substring(0, 24);
  next();
}

// Utility: validate a user-supplied regex pattern to mitigate ReDoS
function isSafeRegexPattern(pattern) {
  if (typeof pattern !== 'string') return false;
  if (pattern.length > 128) return false;
  // Reject nested/adjacent unbounded quantifiers that commonly cause
  // catastrophic backtracking, e.g. (a+)+ , (a*)* , (.+)+ , a{2,}{2,}
  const redosPattern = /(\([^)]*[+*][^)]*\)[+*])|([+*]\s*[+*])|(\{\d*,?\}\s*[+*{])/;
  if (redosPattern.test(pattern)) return false;
  return true;
}

// Utility: build a safe query filter from user-provided search criteria
function buildSearchFilter(criteria) {
  const filter = {};
  const allowedFields = ['name', 'category', 'status', 'priority'];
  const allowedOps = ['$eq', '$ne', '$in', '$regex'];

  for (const [field, condition] of Object.entries(criteria)) {
    if (!allowedFields.includes(field)) continue;

    if (typeof condition === 'string' || typeof condition === 'number') {
      filter[field] = { $eq: condition };
    } else if (typeof condition === 'object' && condition !== null) {
      const sanitized = {};
      for (const [op, val] of Object.entries(condition)) {
        if (!allowedOps.includes(op)) continue;
        if (op === '$regex') {
          // Only accept safe, bounded string patterns to prevent ReDoS.
          if (!isSafeRegexPattern(val)) continue;
        }
        sanitized[op] = val;
      }
      if (Object.keys(sanitized).length > 0) {
        filter[field] = sanitized;
      }
    }
  }
  return filter;
}

// Utility: apply projection normalization
function normalizeProjection(proj) {
  if (!proj || typeof proj !== 'object') return { _id: 1, name: 1, category: 1 };
  const normalized = {};
  const safeFields = ['_id', 'name', 'category', 'status', 'priority', 'createdAt', 'description'];
  for (const [key, val] of Object.entries(proj)) {
    if (safeFields.includes(key) && (val === 1 || val === 0)) {
      normalized[key] = val;
    }
  }
  return Object.keys(normalized).length > 0 ? normalized : { _id: 1, name: 1 };
}

// Utility: build sort safely without server-side evaluation
function buildSortOptions(sortSpec) {
  if (!sortSpec || typeof sortSpec !== 'object') return { createdAt: -1 };

  // Reject any expression-based sorting - only allow field-direction pairs
  if (sortSpec.expression) {
    return { createdAt: -1 };
  }

  const result = {};
  const allowedSortFields = ['name', 'createdAt', 'priority', 'status'];
  for (const [field, dir] of Object.entries(sortSpec)) {
    if (allowedSortFields.includes(field) && (dir === 1 || dir === -1)) {
      result[field] = dir;
    }
  }
  return Object.keys(result).length > 0 ? result : { createdAt: -1 };
}

// Search endpoint
app.post('/api/items/search', authenticate, async (req, res) => {
  try {
    const { criteria, projection, sort, limit } = req.body;

    if (!criteria || typeof criteria !== 'object') {
      return res.status(400).json({ error: 'Invalid criteria' });
    }

    const filter = buildSearchFilter(criteria);
    filter.ownerId = req.userId;

    const proj = normalizeProjection(projection);
    const sortOpts = buildSortOptions(sort);
    const queryLimit = Math.min(Math.max(parseInt(limit) || 20, 1), 100);

    const results = await db.collection('items')
      .find(filter)
      .project(proj)
      .sort(sortOpts)
      .limit(queryLimit)
      .toArray();

    res.json({ results, count: results.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

initDb().then(() => {
  app.listen(3000, '127.0.0.1', () => {
    console.log('Server running on port 3000');
  });
}).catch(err => {
  console.error('Failed to connect to database:', err);
  process.exit(1);
});
